func TestUnselectedAttemptWordIsAccounted(emonT *testing.T) {
	var runs *port.Cells = port.NewCells()
	var words *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var nodes *port.Cells = port.NewCells()
	var regions *port.Cells = port.NewCells()
	var mask *port.Cells = port.NewCells()
	var ledger *port.Cells = port.NewCells()
	var text *port.Cells = port.NewCells()
	var bag *port.Cells = port.NewCells()
	var tokens *port.Cells = port.NewCells()
	var norm *port.Cells = port.NewCells()
	var tmp *port.Cells = port.NewCells()
	var raw *port.Cells = port.NewCells()
	var rt *port.Cells = port.NewCells()
	port.CellsPush(mask, 1)
	port.CellsPush(et, 65)
	evidence.OrNew(runs, 1, 0)
	evidence.OrSet(runs, 0, evidence.OrfWfirst(), 0)
	evidence.OrSet(runs, 0, evidence.OrfWcount(), 1)
	evidence.OwNew(words, 1, 0, 0, 100, 100, 0, 100, 100, 100, 0, 0, 0, 1, 0, 900, -1)
	port.AssertEq(emonT, ocrledger.OcAccount(runs, words, et, nodes, regions, mask, ledger, text, bag, tokens, norm, tmp, raw, rt), 1, "unselected attempt must have an explicit fate")
	port.AssertEq(emonT, model.LedgerCount(ledger), 1, "residual becomes a ledger entry")
	port.AssertEq(emonT, model.LedgerTextLen(ledger, 0), 1, "original OCR text retained")
}

